def keep_current_footer(apps, schema_editor):
    """Until now the footer showed the company name (legal name, or the site name); keep showing it."""
    SiteSettings = apps.get_model("siteconfig", "SiteSettings")
    for site in SiteSettings.objects.all():
        name = site.legal_name or site.name
        for code in ("nl", "en", "de"):
            setattr(site, f"footer_heading_{code}", name)
        site.footer_heading = name
        site.save()


